/** Samakan gaya penulisan dengan template BRS: "TANJUNG PERAK" -> "Tanjung Perak". */
export function gayaBrs(teks) {
  return String(teks).replace(/[A-Za-z]+/g, (kata) => (
    kata.length <= 3 ? kata : kata[0].toUpperCase() + kata.slice(1).toLowerCase()
  ));
}

/** Nama pelabuhan untuk satu kode; kode asli bila tidak dikenal. */
export function namaPelabuhan(kode) {
  if (kode == null) return '-';
  const k = String(kode).trim();
  if (!k) return '-';
  return gayaBrs(PELABUHAN[k]?.n || PELABUHAN[k.toUpperCase()]?.n || k);
}
